description:
Implement `MyRequired<T>` — a mapped type that removes optionality from all properties of `T` — without using the built-in `Required<T>`.

Also implement `requireAll<T>(obj: Partial<T>): MyRequired<T>` that returns the same object cast as `MyRequired<T>`.

**Example:**
```ts
type Config = { host?: string; port?: number };
type StrictConfig = MyRequired<Config>;
// { host: string; port: number }  (no '?')
```

starter_code:
export type MyRequired<T> = // your type here

export function requireAll<T>(obj: Partial<T>): MyRequired<T> {
  return obj as MyRequired<T>;
}

test_suite:
test('requireAll returns the same object', () => {
  const obj = { host: 'localhost', port: 5432 };
  expect(requireAll(obj)).toEqual(obj);
});

test('type-level: all properties become required', () => {
  type T = MyRequired<{ a?: number; b?: string }>;
  type Check = T extends { a: number; b: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: MyRequired matches built-in Required', () => {
  type T = { x?: boolean; y?: number };
  type Check = MyRequired<T> extends Required<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('type-level: -? removes optionality correctly', () => {
  type T = MyRequired<{ name?: string }>;
  type IsRequired = undefined extends T['name'] ? false : true;
  const check: IsRequired = true;
  expect(check).toBe(true);
});

solution:
export type MyRequired<T> = { [K in keyof T]-?: T[K] };

export function requireAll<T>(obj: Partial<T>): MyRequired<T> {
  return obj as MyRequired<T>;
}
